import math

def evaluate(current_reputation, observation, my_history, round_num):
    w = observation.get('recent_window', [])
    if not w:
        return current_reputation
    n = len(w)
    tot = 0.0
    coop = 0.0
    for i, d in enumerate(w):
        wt = 0.9 ** (n - 1 - i)  # more weight to recent
        tot += wt
        if d['action'] == 'cooperate':
            coop += wt
    f = coop / tot
    act = observation['action']
    if act == 'cooperate':
        change = 0.2 * (1 - current_reputation) * (1 - 0.4 * f)
    else:
        change = -0.4 * (1 + abs(current_reputation)) * (1 + 1.2 * f)
    return max(-1.0, min(1.0, current_reputation + change))

def decide(recipient_reputation, round_num, my_history):
    defs = sum(1 for _, a in my_history if a == 'defect')
    coops = sum(1 for _, a in my_history if a == 'cooperate')
    if abs(recipient_reputation) < 0.2:
        return round_num % 2 == 0
    thresh = 0.5 + 0.03 * defs - 0.03 * coops - 0.02 * round_num
    thresh = max(0.1, min(0.9, thresh))
    return recipient_reputation > thresh

