def evaluate(current_reputation, observation, my_history, round_num):
    # Compute cooperation proportion in donor's own history (before this action)
    if my_history:
        coop_count = sum(1 for a in my_history if a == 'cooperate')
        coop_prop = coop_count / len(my_history)
    else:
        coop_prop = 0.5  # neutral if no history

    if observation['action'] == 'cooperate':
        # Reward cooperation more if donor already cooperates often
        update = 0.1 * (1 + coop_prop)
    else:
        # Penalize defection: harsh if donor usually cooperates, milder if defector
        update = -0.5 * (2 - coop_prop)  # ranges from -1.0 to -0.5
    return max(-1.0, min(1.0, current_reputation + update))

def decide(recipient_reputation, round_num, my_history):
    # Compute own cooperation rate from history
    if my_history:
        coop_count = sum(1 for a in my_history if a == 'cooperate')
        own_coop_rate = coop_count / len(my_history)
    else:
        own_coop_rate = 0.5  # neutral start

    # Threshold varies with round and own cooperation rate:
    # More forgiving early (low round) and when we are cooperative ourselves
    base_threshold = 0.3 + 0.2 * (round_num / 15)  # from 0.3 to 0.5
    # Lower threshold (more cooperative) if we have been cooperative often
    adjusted_threshold = base_threshold - 0.2 * own_coop_rate
    # Clamp to ensure meaningful range (0.1 to 0.7)
    adjusted_threshold = max(0.1, min(0.7, adjusted_threshold))
    return recipient_reputation > adjusted_threshold

def evaluate(current_reputation, observation, my_history, round_num):
    # Use recent_window if available to compute donor's cooperation pattern
    if 'recent_window' in observation and observation['recent_window']:
        donor = observation.get('donor', None)
        if donor is not None:
            donor_obs = [entry for entry in observation['recent_window'] if entry.get('donor') == donor]
            if donor_obs:
                coop_count = sum(1 for entry in donor_obs if entry['action'] == 'cooperate')
                coop_rate = coop_count / len(donor_obs)
            else:
                coop_rate = 0.5
        else:
            coop_rate = 0.5
        # Update based on pattern and current action
        if observation['action'] == 'cooperate':
            update = 0.2 * (1 + coop_rate)
        else:
            update = -0.4 * (2 - coop_rate)
    else:
        # Fallback: use own history cooperation proportion
        if my_history:
            coop_prop = sum(1 for a in my_history if a == 'cooperate') / len(my_history)
        else:
            coop_prop = 0.5
        if observation['action'] == 'cooperate':
            update = 0.15 * (1 + coop_prop)
        else:
            update = -0.5 * (2 - coop_prop)
    return max(-1.0, min(1.0, current_reputation + update))

def decide(recipient_reputation, round_num, my_history):
    # Own cooperation rate
    if my_history:
        coop_rate = sum(1 for a in my_history if a == 'cooperate') / len(my_history)
    else:
        coop_rate = 0.5

    # Two thresholds that vary with round and own history
    low = 0.2 + 0.1 * (round_num / 15) - 0.1 * coop_rate
    high = 0.6 - 0.1 * (round_num / 15) - 0.1 * coop_rate
    low = max(0.0, min(1.0, low))
    high = max(low, min(1.0, high))

    if recipient_reputation > high:
        return True
    elif recipient_reputation < low:
        return False
    else:
        # Middle zone: cooperate if early round or we have been cooperative often
        return round_num <= 5 or coop_rate > 0.5

